VERSION='rpf68-cross-domain-verifier-v1'
def identity():
 raw=Path(__file__).read_bytes();return dict(version=VERSION,raw=c.sha(raw),lf=c.sha(raw.replace(b'\r\n',b'\n')))
def seal(p):return dict(schema='rpf68-cross-domain-witness-v1',verifier=identity(),payload=p,payload_sha256=c.digest(p))
def verify_domain(ctx,ct,e):
 index=ct['experiment']['round'];domain=ct['experiment']['domain'];c.require(e['contract']==ct and ct in ctx['rounds'][index-1].values(),'DOMAIN_CONTRACT');trace=e['trace'];lost=ct['experiment']['fault_enabled'];expected=list(c.TOOLS[domain][:(2 if index==2 else 3)]);names=[t['name'] for t in trace];c.require(names==expected or lost and names==expected+[c.TOOLS[domain][0 if index==1 else 2]],'DOMAIN_TOOL_ORDER');c.require(e['fault']==dict.fromkeys(('planned','triggered','observed','agent_exposed'),lost),'FAULT_FOUR_STATES');c.require(all(e['cleanup'].values()) and all(e['sdk']['cleanup'].values()),'DOMAIN_CLEANUP')
