 for i,row in enumerate(requests):
  q,p=row['request'],row['response'];c.require(q['ordinal']==i+1 and q['slot_cap']==c.CAPS[domain][i] and q['output_cap']==(512 if i>=len(expected) or index==2 and i>=2 else 256) and q['input_upper']+q['output_cap']<=q['slot_cap'],'DOMAIN_REQUEST_CAP')
  c.require(all(type(q[k]) is int and q[k]>=0 for k in ('input_upper','canonical_bytes','suffix_bytes','framing_guard')),'INPUT_INTEGER')
  if i==0:c.require(q['previous_prompt'] is None and q['suffix_bytes']==q['framing_guard']==0 and q['input_upper']==q['canonical_bytes'],'INITIAL_INPUT_PROOF')
