 b=e['business'];c.require(b['oracle']['contract_outcome']=='CONTRACT_SATISFIED_IN_RUN','ORACLE_VERDICT')
 if index==1:
  effect=ct['effect'];http=b['http'];kinds=['initial_current','initial_history','inspect_config','create_config_v1','update_config_v2']+(['inspect_config'] if len(trace)==4 else [])+['reconcile_current','reconcile_history','final_list'];c.require(b['backend']=='REAL_JAVA_H2_HTTP' and [x['kind'] for x in http]==kinds and b['before']==http[:2] and b['after']==http[-3:],'HTTP_SEQUENCE')
  for i,(o,kind) in enumerate(zip(http,kinds)):
   method,path,body=_http_contract(effect,kind);c.require((o['method'],o['path'],o['request'])==(method,path,body) and o['response_body_sha256']==c.digest(o['response']),'HTTP_REQUEST_BINDING');absent=i in (0,2);listed=kind.endswith('history') or kind=='final_list';ok,data=_api_response(o,404 if absent else 200,4041 if absent else 0,'none' if absent else 'list' if listed else 'item');c.require(ok,'HTTP_AUTHORITY')
